"""Render the frozen candidate pack to DOCX. Deterministic, no network.

Outputs are byte-reproducible from the frozen .txt sources: python-docx stamps a
fixed created/modified timestamp (2013-12-23T23:15:00Z) into docProps/core.xml, so
re-running produces identical bytes. Verified by regenerating twice and comparing
SHA-256.

Usage:
    python tests/fixtures/realistic_candidate/render_docx.py
"""
from __future__ import annotations

import hashlib
import io
from pathlib import Path

from docx import Document
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.shared import Pt

HERE = Path(__file__).resolve().parent

# Fixed metadata, matching what python-docx already writes by default. Stated
# explicitly so a library upgrade that changes the default cannot silently alter
# the hashes.
FIXED = """
"""

# python-docx writes this timestamp by default; declared here so the fixture's
# reproducibility does not depend on an undocumented library default.
_CORE_TEMPLATE = (
    "<?xml version='1.0' encoding='UTF-8' standalone='yes'?>\n"
    "<cp:coreProperties "
    "xmlns:cp=\"http://schemas.openxmlformats.org/package/2006/metadata/core-properties\" "
    "xmlns:dc=\"http://purl.org/dc/elements/1.1/\" "
    "xmlns:dcterms=\"http://purl.org/dc/terms/\" "
    "xmlns:dcmitype=\"http://purl.org/dc/dcmitype/\" "
    "xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\">"
    "<dc:title/><dc:subject/><dc:creator>python-docx</dc:creator>"
    "<cp:keywords/><dc:description>generated by python-docx</dc:description>"
    "<cp:lastModifiedBy/><cp:revision>1</cp:revision>"
    "<dcterms:created xsi:type=\"dcterms:W3CDTF\">2013-12-23T23:15:00Z</dcterms:created>"
    "<dcterms:modified xsi:type=\"dcterms:W3CDTF\">2013-12-23T23:15:00Z</dcterms:modified>"
    "<cp:category/></cp:coreProperties>"
)


def render(source: Path, target: Path) -> None:
    """Render the markdown-ish résumé source to a DOCX with normal formatting."""
    document = Document()
    style = document.styles["Normal"]
    style.font.name = "Calibri"
    style.font.size = Pt(10)

    for raw in source.read_text(encoding="utf-8").splitlines():
        line = raw.rstrip()
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith("## "):
            # Section heading
            p = document.add_paragraph()
            run = p.add_run(stripped[3:].strip())
            run.bold = True
            run.font.size = Pt(12)
        elif stripped.startswith("**") and "--" in stripped:
            # Employer line: bold name, then location
            name, _, location = stripped.partition("--")
            p = document.add_paragraph()
            p.add_run(name.strip().strip("*")).bold = True
            p.add_run(" -- " + location.strip())
        elif stripped.startswith("*") and stripped.endswith("*"):
            # Role / degree sub-line, italic
            p = document.add_paragraph()
            p.add_run(stripped.strip("*").strip()).italic = True
        elif stripped.startswith("- "):
            # Bullet
            document.add_paragraph(stripped[2:].strip(), style="List Bullet")
        else:
            document.add_paragraph(stripped)

    # Keep the trailer minimal and stable.
    buffer = io.BytesIO()
    document.save(buffer)
    target.write_bytes(buffer.getvalue())


def main() -> int:
    pairs = [
        (HERE / "candidate-main.txt", HERE / "candidate-main.docx"),
        (HERE / "candidate-supplement.txt", HERE / "candidate-supplement.docx"),
    ]
    for source, target in pairs:
        render(source, target)
        digest = hashlib.sha256(target.read_bytes()).hexdigest()
        print(f"{target.name}  {len(target.read_bytes()):>7} bytes  {digest}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
